rows[78151]={title={{7,64710654},"영웅심"},description={"^increases melee, ranged, and spell casting speed by ([%+%-]?%d[%d,.%+%-to –]*)%% for all party and raid members%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","모든 파티원과 공격대원의 근접 및 원거리 공격 속도와 주문 시전 속도를 \0311\031%만큼 증가시킵니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^melee, ranged, and spell casting speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","근접, 원거리 공격 속도 및 주문 시전 속도 \0311\031%만큼 증가",{0},{1}}}
rows[78152]={title={{16,471148632},"소용돌이치는 무기"},description={"^reduces the cast time of your next lightning bolt, chain lightning, lesser healing wave, healing wave or chain heal spell by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","다음 번개 화살, 연쇄 번개, 하급 치유의 물결, 치유의 물결, 연쇄 치유 주문의 시전 시간이 \0311\031%만큼 감소합니다.",{0},{1}},aura={"^reduces the cast time of your next lightning bolt, chain lightning, lesser healing wave, healing wave or chain heal spell by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","다음 번개 화살, 연쇄 번개, 하급 치유의 물결, 치유의 물결, 연쇄 치유 주문의 시전 시간 \0311\031%만큼 감소",{0},{1}}}
rows[78153]={title={{16,471148632},"소용돌이치는 무기"},description={"^when you deal damage with a melee weapon, you have a chance to reduce the cast time of your next lightning bolt, chain lightning, lesser healing wave, chain heal or healing wave spell by ([%+%-]?%d[%d,.%+%-to –]*)%%%. stacks up to 5 times%.$","근접 공격으로 피해를 입히면 일정 확률로 다음 번개 화살, 연쇄 번개, 하급 치유의 물결, 연쇄 치유, 치유의 물결 주문의 시전 시간이 \0311\031%만큼 감소합니다. 5번까지 중복됩니다.",{0},{1}}}
