rows[79857]={title={{10,217409421},"화염 폭풍"},description={"^unleashes a wave of flame, inflicting fire damage to nearby enemies and reducing their movement speed for ([%+%-]?%d[%d,.]* %a+)%.$","주위로 불의 파도를 뿜어 주위 적에게 화염 피해를 입히고 \0311\031 동안 이동 속도를 감소시킵니다.",{1},{1}},aura={{23,288320887},"이동 속도 감소"}}
rows[79858]={title={{9,1999415615},"얼음 화살"},description={"^inflicts frost damage to an enemy and reduces its movement speed for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 냉기 피해를 입히고 \0311\031 동안 이동 속도를 감소시킵니다.",{1},{1}},aura={{23,288320887},"이동 속도 감소"}}
rows[79859]={title={{9,585971411},"얼음창"},description={{83,244760520},"적에게 냉기 피해를 입힙니다. 얼어붙은 대상에게는 2배의 피해를 입힙니다."}}
rows[79860]={title={{8,157065659},"눈보라"},description={"^calls down a blizzard that lasts ([%+%-]?%d[%d,.]* %a+)%., inflicting frost damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. to all enemies in a selected area%.$","\0311\031 동안 눈보라를 일으켜 그 지역 안의 모든 적에게 \0312\031초마다 냉기 피해를 입힙니다.",{1,0},{1,2}}}
