rows[79863]={title={{10,340732060},"과다출혈"},description={"^deals weapon damage and increases the physical damage taken by an enemy by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","무기 공격력만큼의 피해를 입히고 \0312\031 동안 받는 물리 피해를 \0311\031%만큼 증가시킵니다.",{0,1},{1,2}},aura={"^physical damage taken is increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","받는 물리 피해 \0311\031%만큼 증가",{0},{1}}}
