rows[79865]={title={{11,332297099},"냉기 갑옷"},description={"^encases the caster in a layer of frost that lasts ([%+%-]?%d[%d,.]* %a+)%. the thick ice increases armor, slows melee attackers' movement, and increases the time between their attacks%.$","\0311\031 동안 시전자를 냉기 갑옷으로 감쌉니다. 두꺼운 얼음으로 인해 방어도가 증가하며, 근접 공격자의 이동 속도를 감소시키고 공격 간격을 늘입니다.",{1},{1}},aura={"^armor increased by ([%+%-]?%d[%d,.%+%-to –]*)%. slowing melee attackers' movement and attacks%.$","방어도 \0311\031만큼 증가\010근접 공격자의 이동 및 공격 속도 저하",{0},{1}}}
rows[79866]={title={{12,1290022958},"죽음의 투척"},description={"^throws a dagger at an enemy target, dealing ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage%. it also interrupts spellcasting and prevents any spell in that school from being cast for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 단검을 던져 무기 공격력의 \0311\031%에 해당하는 피해를 입힙니다. 또한 대상이 \0312\031 동안 같은 계열의 주문을 시전하는 것을 방해합니다.",{0,1},{1,2}}}
