rows[79870]={title={{12,1670027063},"야성의 돌진"},description={"^causes you to charge an enemy, immobilizing and interrupting any spell being cast for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 돌진하여 이동 불가 상태로 만들고 \0311\031 동안 주문 시전을 방해합니다.",{1},{1}},aura={{12,1673095295},"이동 불가"}}
rows[79871]={title={{12,392399328},"무모한 희생"},description={"^immune to fear effects%. all attacks are critical hits%. armor reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공포 효과에 면역이 됩니다.\010모든 공격이 치명타로 적중합니다.\010방어도가 \0311\031%만큼 감소합니다.",{0},{1}},aura={"^immune to fear effects%. all attacks are critical hits%. armor reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공포 효과에 면역\010모든 공격이 치명타로 적중\010방어도 \0311\031%만큼 감소",{0},{1}}}
rows[79872]={title={{9,1589415792},"충격파"},description={"^sends a wave of force in front of the warrior, causing damage and stunning all enemy targets within ([%+%-]?%d[%d,.%+%-to –]*) yards in a frontal cone for ([%+%-]?%d[%d,.]* %a+)%.$","충격의 파장을 내보내 전방 \0311\031미터 안에 있는 모든 적 대상에게 피해를 입히고 \0312\031 동안 기절시킵니다.",{0,1},{1,2}},aura={{8,318235535},"기절함"}}
