rows[79876]={title={{11,2056371644},"피의 갈증"},description={"^heals the caster for ([%+%-]?%d[%d,.%+%-to –]*)%% of maximum health%.$","최대 생명력의 \0311\031%에 해당하는 생명력을 회복합니다.",{0},{1}}}
rows[79877]={title={{11,2056371644},"피의 갈증"},description={"^instantly attack the target causing ([%+%-]?%d[%d,.%+%-to –]*)%% of normal weapon damage%. in addition, successful melee attacks will restore 1%% of maximum health%. this effect lasts ([%+%-]?%d[%d,.]* %a+)%.$","즉시 적을 공격하여 무기 공격력의 \0311\031%에 해당하는 피해를 입힙니다. 추가로 다음 근접 공격을 성공할 시 최대 생명력의 1%에 해당하는 생명력을 회복합니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={{29,1326281875},"근접 공격 시 생명력 회복"}}
rows[79878]={title={{11,2056371644},"피의 갈증"},description={"^instantly attack the target causing ([%+%-]?%d[%d,.%+%-to –]*)%% of normal weapon damage%. in addition, successful melee attacks will restore 1%% of maximum health%. this effect lasts ([%+%-]?%d[%d,.]* %a+)%.$","즉시 적을 공격하여 무기 공격력의 \0311\031%에 해당하는 피해를 입힙니다. 추가로 다음 근접 공격을 성공할 시 최대 생명력의 1%에 해당하는 생명력을 회복합니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}}}
rows[79879]={title={{20,761918362},"전하 방출"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage to up to 3 enemies within 8 yards%.$","8미터 반경 내 최대 3명의 적에게 \0311\031의 자연 피해를 입힙니다.",{0},{1}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage to up to 3 enemies within 8 yards%.$","8미터 반경 내 최대 3명의 적에게 \0311\031의 자연 피해",{0},{1}}}
rows[79880]={title={{4,260398513},"감속"},description={"^increases the time between an enemy's attacks by ([%+%-]?%d[%d,.%+%-to –]*)%%, casting time increased by ([%+%-]?%d[%d,.%+%-to –]*)%% and slows its movement by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","\0314\031 동안 적의 공격 간격을 \0311\031%만큼 늘이고, 주문 시전 시간을 \0312\031%만큼 지연시키며, 이동 속도를 \0312\031%만큼 감소시킵니다.",{0,0,0,1},{1,2,2,4}},aura={"^movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. time between melee and ranged attacks increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. casting time increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 감소\010근접 및 원거리 공격 간격 \0312\031%만큼 늘어남\010주문 시전 시간 \0312\031%만큼 지연",{0,0,0},{1,2,2}}}
