rows[79891]={title={{14,2059126306},"겨울의 뿔피리"},description={"^the death knight blows the horn of winter, which generates 10 runic power and increases total strength and agility by ([%+%-]?%d[%d,.%+%-to –]*)%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","죽음의 기사가 겨울의 뿔피리를 불어 10의 룬 마력을 얻고 \0312\031 동안 전체 힘과 민첩성을 \0311\031만큼 증가시킵니다.",{0,1},{1,2}},aura={"^increases your total strength and agility by ([%+%-]?%d[%d,.%+%-to –]*)%.$","전체 힘 및 민첩성 \0311\031만큼 증가",{0},{1}}}
