rows[79894]={title={{10,1398899180},"죽음의 손아귀"},description={"^harness the unholy energy that surrounds and binds all matter, drawing the target toward the caster and forcing the enemy to attack the caster for ([%+%-]?%d[%d,.]* %a+)%.$","모든 물질을 감싸고 결합시키는 부정의 힘을 이용해 대상을 끌어당기고 \0311\031 동안 자신을 공격하게 만듭니다.",{1},{1}}}
