rows[79897]={title={{9,1328669160},"얼음 손길"},description={"^deals frost damage and reduces the target's ranged, melee attack, and casting speed by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","대상에게 냉기 피해를 입히고 \0312\031 동안 대상의 원거리 및 근접 공격 속도와 주문 시전 속도를 \0311\031%만큼 감소시킵니다.",{0,1},{1,2}},aura={"^attack and casting speeds reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공격 및 주문 시전 속도 \0311\031%만큼 감소",{0},{1}}}
