rows[79899]={title={{13,988110214},"얼음 결계"},description={"^shackles the target with frozen chains, reducing their movement to 5%% of normal%. the target regains 10%% of their movement each second for ([%+%-]?%d[%d,.]* %a+)%.$","대상을 얼음의 사슬로 속박하여 이동 속도를 평소의 5%로 감소시킵니다. 대상은 1초마다 이동 속도를 10%씩 회복합니다. \0311\031 동안 지속됩니다.",{1},{1}},aura={{7,1965809786},"감속"}}
rows[79900]={title={{15,1444559760},"불안정한 보호막"},description={"^attacks against the unstable shield cause a static shock at a nearby enemy's location%. static shock inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards of the target%.$","불안정한 보호막을 대상으로 공격 시 주변의 적 위치에 전하 충격을 일으킵니다. 전하 충격은 대상으로부터 \0312\031미터 반경 내의 적에게 \0311\031의 자연 피해를 입힙니다.",{0,0},{1,2}},aura={{48,174971820},"공격 시 전하 충격 유발"}}
rows[79901]={title={{12,2088182930},"피의 역병"},description={"^a vicious strike that deals weapon damage and plagues the target, dealing shadow damage over ([%+%-]?%d[%d,.]* %a+)%.$","무기 공격력만큼 피해를 입히고 대상을 감염시켜 \0311\031에 걸쳐 암흑 피해를 입힙니다.",{1},{1}},aura={"^deals shadow damage over ([%+%-]?%d[%d,.]* %a+)%.$","\0311\031에 걸쳐 암흑 피해",{1},{1}}}
rows[79902]={title={{13,532181188},"역병의 일격"},description={"^a vicious strike that deals weapon damage and plagues the target, dealing ([%+%-]?%d[%d,.%+%-to –]*) shadow damage over ([%+%-]?%d[%d,.]* %a+)%.$","무기 공격력만큼의 피해를 입히고 대상을 감염시켜 \0312\031에 걸쳐 \0311\031의 암흑 피해를 입힙니다.",{0,1},{1,2}}}
