rows[79954]={title={{9,1902650080},"마의 갑옷"},description={"^surrounds the caster with fel energy, increasing spell power by ([%+%-]?%d[%d,.%+%-to –]*)%%%. in addition, you regain ([%+%-]?%d[%d,.%+%-to –]*)%% of your maximum health every 5 sec%. only one type of armor spell can be active at any time%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","자신을 마의 에너지로 감싸 주문력이 \0311\031%만큼 증가하고, 5초마다 최대 생명력의 \0312\031%를 회복합니다. 흑마법사의 갑옷 주문은 한 번에 한 종류만 사용할 수 있습니다. \0313\031 동안 지속됩니다.",{0,0,1},{1,2,3}},aura={"^increases spell power by ([%+%-]?%d[%d,.%+%-to –]*)%%%. also regenerate ([%+%-]?%d[%d,.%+%-to –]*)%% of maximum health every 5 sec%.$","주문력 \0311\031%만큼 증가\0105초마다 최대 생명력의 \0312\031% 회복",{0,0},{1,2}}}
