rows[79956]={title={{21,1493002981},"원소의 저주"},description={"^curses the target for ([%+%-]?%d[%d,.]* %a+), reducing arcane, fire, frost, nature, and shadow resistances by ([%+%-]?%d[%d,.%+%-to –]*) and increasing magic damage taken by ([%+%-]?%d[%d,.%+%-to –]*)%%%. only one curse per caster can be active on any one target%.$","저주를 걸어 \0311\031 동안 대상의 비전, 화염, 냉기, 자연, 암흑 저항력을 \0312\031만큼 감소시키고 받는 마법 피해를 \0313\031%만큼 증가시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다.",{1,0,0},{1,2,3}},aura={"^reduces arcane, fire, frost, nature and shadow resistances by ([%+%-]?%d[%d,.%+%-to –]*)%. increases magic damage taken by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","비전, 화염, 냉기 자연, 암흑 저항력 \0311\031만큼 감소\010받는 마법 피해 \0312\031%만큼 증가",{0,0},{1,2}}}
rows[79957]={title={{9,276863087},"영혼의 고리"},description={"^when active, ([%+%-]?%d[%d,.%+%-to –]*)%% of all damage taken by the caster is taken by your imp, voidwalker, succubus, felhunter, felguard, or enslaved demon instead%. that damage cannot be prevented%. lasts as long as the demon is active and controlled%.$","활성화되면 시전자가 받는 모든 피해의 \0311\031%는 소환한 임프나 공허방랑자, 서큐버스, 지옥사냥개, 지옥수호병, 지배한 악마가 대신 입게 됩니다. 이로 인한 피해는 막을 수 없습니다. 소환수를 부리는 동안 지속됩니다.",{0},{1}}}
