rows[79977]={title={{17,1172197928},"힘의 축복"},description={"^places a blessing on the friendly target, increasing attack power by ([%+%-]?%d[%d,.%+%-to –]*)%% and ranged attack power by ([%+%-]?%d[%d,.%+%-to –]*)%%, and restoring ([%+%-]?%d[%d,.%+%-to –]*)%% mana every 5 seconds for ([%+%-]?%d[%d,.]* %a+)%.$","아군 대상에게 힘의 축복을 걸어 \0314\031 동안 근접 전투력을 \0311\031%만큼, 원거리 전투력을 \0312\031%만큼 증가시키고 5초마다 \0313\031%의 마나를 회복시킵니다.",{0,0,0,1},{1,2,3,4}},aura={"^increases attack power by ([%+%-]?%d[%d,.%+%-to –]*)%% and ranged attack power by ([%+%-]?%d[%d,.%+%-to –]*)%%, and restores ([%+%-]?%d[%d,.%+%-to –]*)%% mana every 5 sec%.$","근접 전투력 \0311\031%만큼, 원거리 전투력 \0312\031%만큼 증가\0105초마다 \0313\031%의 마나 회복",{0,0,0},{1,2,3}}}
