rows[80003]={title={{11,1354588250},"검은 화살"},description={"^fires a black arrow at the target, increasing all damage done by you to the target by ([%+%-]?%d[%d,.%+%-to –]*)%% and dealing shadow damage over ([%+%-]?%d[%d,.]* %a+)$","적에게 검은 화살을 쏴 자신이 대상에게 입히는 모든 피해를 \0311\031%만큼 증가시키고 \0312\031에 걸쳐 암흑 피해를 입힙니다.",{0,1},{1,2}},aura={"^all damage taken increased by ([%+%-]?%d[%d,.%+%-to –]*)%%, and inflicts shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","받는 모든 피해 \0311\031%만큼 증가\010\0312\031초마다 암흑 피해",{0,0},{1,2}}}
rows[80004]={title={{10,1667323440},"뱀 덫"},description={"^place a trap that will release several venomous snakes to attack the first enemy to approach%. the snakes will die after ([%+%-]?%d[%d,.]* %a+)%. trap will exist for ([%+%-]?%d[%d,.]* %a+)$","덫을 설치합니다. 적이 다가오면 독사가 풀려나 처음으로 덫을 건드린 적을 공격합니다. 뱀은 \0311\031 후에 죽습니다. 덫은 \0312\031 동안 지속됩니다.",{1,1},{1,2}}}
