rows[80011]={title={{16,1843942839},"독에 젖음"},description={"^being soaked in poison inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) sec and causes spells and abilities to inflict ([%+%-]?%d[%d,.%+%-to –]*) nature damage to the target%.$","독에 젖어 \0312\031초마다 \0311\031의 자연 피해를 입고 주문 및 능력 사용 시 대상에게 \0313\031의 자연 피해를 입힙니다.",{0,0,0},{1,2,3}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. attacks cause you to expunge the poison, inflicting ([%+%-]?%d[%d,.%+%-to –]*) nature damage to the target%.$","\0312\031초마다 \0311\031의 자연 피해\010공격 시 독이 해소되며 대상에게 \0313\031의 자연 피해",{0,0,0},{1,2,3}}}
rows[80012]={title={{12,1488571129},"키메라 사격"},description={"^you deal ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage, refreshing the current sting on your target and triggering an effect: serpent sting %- instantly deals 40%% of the damage done by your serpent sting%. viper sting %- instantly restores mana to you equal to 60%% of the total amount drained by your viper sting%. scorpid sting %- attempts to disarm the target for 10 sec%. this effect cannot occur more than once per 1 minute%.$","무기 공격력의 \0311\031%에 해당하는 피해를 입힙니다. 대상에 걸린 쐐기를 다시 시작하게 하고 추가 효과를 일으킵니다:\010\010독사 쐐기 - 즉시 살무사 쐐기 공격력의 40%에 해당하는 피해를 입니다.\010\010살무사 쐐기 - 살무사 쐐기로 소진된 마나의 60%에 해당하는 마나를 즉시 회복합니다.\010\010전갈 쐐기 - 10초 동안 대상에게 무장 해제를 시도합니다. 이 효과는 1분에 1번씩만 발동됩니다.",{0},{1}}}
rows[80013]={title={{22,1061280255},"키메라 사격 - 독사"},description={"^you deal ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage, refreshing the current sting on your target and triggering an effect: serpent sting %- instantly deals 40%% of the damage done by your serpent sting%. viper sting %- instantly restores mana to you equal to 60%% of the total amount drained by your viper sting%. scorpid sting %- attempts to disarm the target for 10 sec%. this effect cannot occur more than once per 1 minute%.$","무기 공격력의 \0311\031%에 해당하는 피해를 입힙니다. 대상에 걸린 쐐기를 다시 시작하게 하고 추가 효과를 일으킵니다:\010\010독사 쐐기 - 즉시 살무사 쐐기 공격력의 40%에 해당하는 피해를 입니다.\010\010살무사 쐐기 - 살무사 쐐기로 소진된 마나의 60%에 해당하는 마나를 즉시 회복합니다.\010\010전갈 쐐기 - 10초 동안 대상에게 무장 해제를 시도합니다. 이 효과는 1분에 1번씩만 발동됩니다.",{0},{1}}}
rows[80014]={title={{14,2120070239},"독 해소"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage to the target of your spells and abilities%.$","주문 및 능력의 대상에게 \0311\031의 자연 피해를 입힙니다.",{0},{1}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage to the target of your spells and abilities%.$","주문 및 능력의 대상에게 \0311\031의 자연 피해를 입힙니다.",{0},{1}}}
rows[80015]={title={{11,1939664532},"고정 사격"},description={"^a steady shot that causes ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage as physical%.$","안정적으로 사격하여 무기 공격력의 \0311\031%에 달하는 물리 피해를 입힙니다.",{0},{1}}}
rows[80016]={title={{13,1688223218},"사냥꾼의 징표"},description={"^places the hunter's mark on the target, increasing the ranged damage of all attackers against that target by ([%+%-]?%d[%d,.%+%-to –]*)%%%. in addition, the target of this ability can always be seen by the hunter whether it stealths or turns invisible%. lasts for ([%+%-]?%d[%d,.]* %a+)%.$","대상에게 사냥꾼의 징표를 겁니다. 징표가 걸린 대상을 공격하는 이는 대상에 대한 원거리 전투력이 \0311\031%만큼 증가합니다. 추가로 이 능력에 걸린 대상은 은신이나 투명 상태에서도 사냥꾼의 시야에 보입니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^all ranged attackers do ([%+%-]?%d[%d,.%+%-to –]*)%% additional damage against this target%.$","이 대상에 대한 원거리 피해 \0311\031%만큼 증가",{0},{1}}}
