rows[80018]={title={{10,1979623359},"냉기의 덫"},description={"^place a frost trap that creates an ice slick around itself for ([%+%-]?%d[%d,.]* %a+) when the first enemy approaches it%. all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards will be slowed by ([%+%-]?%d[%d,.%+%-to –]*)%% while in the area of effect%. trap will exist for ([%+%-]?%d[%d,.]* %a+)%. only one trap can be active at a time%.$","냉기의 덫을 설치합니다. 적이 다가오면 덫에서 가느다란 얼음실이 퍼져 나와, \0311\031 동안 \0312\031미터 반경 이내 적의 이동 속도를 \0313\031%만큼 감소시킵니다. 덫은 \0311\031 동안 지속되며, 한 개만 놓아둘 수 있습니다.",{1,0,0,1},{1,2,3,1}}}
rows[80019]={title={{15,1721838747},"냉기의 덫 오라"},description={"^place a frost trap that creates an ice slick around itself for ([%+%-]?%d[%d,.]* %a+) when the first enemy approaches it%. all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards will be slowed by ([%+%-]?%d[%d,.%+%-to –]*)%% while in the area of effect%.$","냉기의 덫을 설치합니다. 적이 다가오면 덫에서 가느다란 얼음실이 퍼져 나와, \0311\031 동안 \0312\031미터 반경 이내 적의 이동 속도를 \0313\031%만큼 감소시킵니다.",{1,0,0},{1,2,3}},aura={"^movement speed slowed by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 감소",{0},{1}}}
rows[80020]={title={{13,753758256},"야수의 격노"},description={"^send your pet into a rage causing ([%+%-]?%d[%d,.%+%-to –]*)%% additional damage for ([%+%-]?%d[%d,.]* %a+)%. while enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed%.$","야수를 광폭하게 만들어 \0312\031 동안 공격력을 \0311\031%만큼 증가시킵니다. 광포한 동안엔 어떠한 방법으로도 공격을 저지할 수 없습니다.",{0,1},{1,2}},aura={{8,2001102030},"광포해짐"}}
