rows[81700]={title={{9,1523780261},"대천사"},description={"^consumes your evangelism, increasing your healing done by ([%+%-]?%d[%d,.%+%-to –]*)%% for each evangelism consumed for ([%+%-]?%d[%d,.]* %a+)%.$","사도 효과를 소모하여, \0312\031 동안 효과 하나당 치유량을 \0311\031%만큼 증가시킵니다.",{0,1},{1,2}},aura={"^healing increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","치유량 \0311\031%만큼 증가",{0},{1}}}
rows[81701]={title={{15,1981316074},"타락한 피"},description={"^your blood is corrupted! increases damage taken from corruption of the old god by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","타락한 피 효과를 얻어 고대 신의 타락으로 입는 피해가 \0311\031%만큼 증가합니다.",{0},{1}},aura={"^increases damage taken from corruption of the old god by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","고대 신의 타락으로 입는 피해 \0311\031%만큼 증가",{0},{1}}}
rows[81702]={title={{16,3937788},"무두 용액"},description={"^the tanning solution inflicts nature damage and causes you to choke, reducing your chance to hit by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","무두 용액으로 자연 피해를 입고, 숨이 막혀 \0312\031 동안 적중률이 \0311\031%만큼 감소합니다.",{0,1},{1,2}},aura={"^reduces chance to hit by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","적중률 \0311\031%만큼 감소",{0},{1}}}
