rows[81705]={title={{11,1551532465},"가죽 베기"},description={"^an instant attack that deals 50%% weapon damage and reduces intellect and spirit by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","즉시 공격하여 무기 공력력의 50%에 해당하는 피해를 입히고 \0312\031 동안 지능과 정신력을 \0311\031%만큼 감소시킵니다.",{0,1},{1,2}},aura={"^intellect reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. spirit reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","지능 \0311\031%만큼 감소\010정신력 \0312\031%만큼 감소",{0,0},{1,2}}}
rows[81706]={title={{13,1371814945},"맹독의 분노"},description={"^increases damage dealt by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031 동안 공격력이 \0311\031%만큼 증가합니다.",{0,1},{1,2}},aura={"^increases damage dealt by ([%+%-]?%d[%d,.%+%-to –]*)%%$","공격력 \0311\031%만큼 증가",{0},{1}}}
rows[81707]={title={{8,465516747},"질풍"},description={"^bolstered by a curious zephyr%. melee, ranged, and spell%-casting speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","특이한 미풍의 힘을 받습니다. 근접, 원거리 및 주문 시전 속도가 \0311\031%만큼 증가합니다.",{0},{1}},aura={"^melee and ranged attack speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. spell%-casting speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","근접 및 원거리 공격 속도 \0311\031%만큼 증가\010주문 시전 속도 \0311\031%만큼 증가",{0,0},{1,1}}}
rows[81708]={title={{9,321127727},"활력"},description={"^uses your skill in herbalism to absorb energy and nutrients from the earth, instantly healing minor wounds and granting ([%+%-]?%d[%d,.%+%-to –]*) haste for ([%+%-]?%d[%d,.]* %a+)%. can be used while stealthed or invisible%.$","약초채집으로 익힌 기술로 땅에서 에너지와 영양분을 흡수하여 즉시 작은 상처를 치료하고 \0312\031에 걸쳐 \0311\031의 가속 증가 효과를 받습니다. 은신이나 투명 상태에서 사용할 수 있습니다.",{0,1},{1,2}},aura={"^haste increased by ([%+%-]?%d[%d,.%+%-to –]*)%.$","가속 \0311\031만큼 증가",{0},{1}}}
